'use strict';
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),assert=require('node:assert/strict'),zlib=require('node:zlib');
const {BROWSER_HEADERS}=require('../../../scripts/csp-live-audit.cjs');
const dir=process.argv[2];fs.mkdirSync(dir,{recursive:true});
const origin='https://app.chasingmajors.com',pages=['index.html','checklists/index.html','vault/index.html','ChatBot/index.html'];
const manifest={origin,captured_at:new Date().toISOString(),resources:{},pages:{},analytics_token:'00000000-0000-4000-8000-000000000001',report_endpoint:'https://csp-report.chasingmajors.com/report'};
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
async function download(url,headers=BROWSER_HEADERS){const r=await fetch(url,{headers,cache:'no-store',signal:AbortSignal.timeout(30000)});assert(r.ok,'Fixture HTTP '+r.status+' '+url);assert.equal(new URL(r.url).origin,new URL(url).origin);return {body:Buffer.from(await r.arrayBuffer()),headers:r.headers};}
async function save(url,kind,expected){if(manifest.resources[url])return;const {body}=await download(url,kind==='css'?{...BROWSER_HEADERS,accept:'text/css,*/*;q=0.1'}:undefined);if(expected)assert.equal('sha512-'+crypto.createHash('sha512').update(body).digest('base64'),expected,'Beacon integrity mismatch');const file=hash(body)+({css:'.css',font:'.woff2',script:'.js'}[kind]);fs.writeFileSync(path.join(dir,file),body);manifest.resources[url]={file,kind,bytes:body.length,sha256:hash(body)};return body;}
(async()=>{
 const baseline=JSON.parse(fs.readFileSync(path.join(__dirname,'baseline/manifest.json')));
 for(const page of pages){const pathname=page==='index.html'?'/':'/'+page.replace('index.html','');const url=origin+pathname;const plain=await download(url,{}),browser=await download(url);const html=browser.body.toString();const injection=html.match(/<script\b[^>]*src="https:\/\/static\.cloudflareinsights\.com[^>]*>[\s\S]*?<\/script>/i)?.[0];assert(injection,'Missing browser-like beacon: '+page);const src=injection.match(/src="([^"]+)"/)[1],integrity=injection.match(/integrity="([^"]+)"/)[1];assert.equal(new URL(src).origin,'https://static.cloudflareinsights.com');assert.equal(hash(plain.body),baseline.pages[page].sha256,'Live baseline changed: '+page);const mutation=[injection,injection+'\n','\n'+injection].find(part=>html.includes(part)&&hash(Buffer.from(html.replace(part,'')))===baseline.pages[page].sha256);assert(mutation,'Unexpected browser HTML mutation beyond beacon/adjacent LF: '+page);manifest.pages[page]={paths:[pathname,'/'+page],plain_sha256:hash(plain.body),browser_sha256:hash(browser.body),injected_bytes:Buffer.byteLength(injection),beacon_src:src,beacon_integrity:integrity,beacon_element:mutation.replace(/("token"\s*:\s*")[^"]+/g,'$1'+manifest.analytics_token),report_only:browser.headers.get('content-security-policy-report-only'),enforcing:browser.headers.get('content-security-policy')};assert(manifest.pages[page].report_only&&!manifest.pages[page].enforcing);await save(src,'script',integrity);}
 const styles=['https://fonts.googleapis.com/css2?family=Bangers&family=Archivo:wght@600;700;800;900&display=swap','https://fonts.googleapis.com/css2?family=Bangers&display=swap'];
 for(const url of styles){const css=await save(url,'css');for(const m of css.toString().matchAll(/url\((https:\/\/fonts\.gstatic\.com\/[^)]+)\)/g))await save(m[1],'font');}
 fs.writeFileSync(path.join(dir,'manifest.json'),JSON.stringify(manifest,null,2)+'\n');
 console.log(JSON.stringify({pages:Object.keys(manifest.pages).length,resources:Object.values(manifest.resources).map(r=>({kind:r.kind,bytes:r.bytes})),beacon_injected_bytes:Object.values(manifest.pages).map(p=>p.injected_bytes)}));
})().catch(e=>{console.error(e.stack);process.exitCode=1});
